insert into public.person_core(user_id,display_name) values ('71000000-0000-4000-8000-000000000001','Report author'),('71000000-0000-4000-8000-000000000006','Moderator') on conflict(user_id) do update set display_name=excluded.display_name;
insert into public.platform_admins(user_id) values ('71000000-0000-4000-8000-000000000006');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is(public.is_platform_admin(),false,'Normal user is not admin');
select extensions.lives_ok($$select public.report_network_interaction('73000000-0000-4000-8000-000000000004','spam','Legacy report')$$,'Legacy reporting still works');
select extensions.lives_ok($$select public.report_network_conversation('74000000-0000-4000-8000-000000000001','harassment','Contact report')$$,'Contact conversation reporting works');
select extensions.lives_ok($$select public.report_network_conversation('74000000-0000-4000-8000-000000000002','other','Problem report')$$,'Problem conversation reporting works');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select extensions.lives_ok($$select public.report_network_conversation('74000000-0000-4000-8000-000000000003','misleading','FIND report')$$,'FIND reporting still works without CONNECT membership');
reset role;
-- Stable IDs only inside this rollback-only fixture.
update public.network_reports set id = ('76000000-0000-4000-8000-' || case comment when 'Legacy report' then '000000000004' when 'Contact report' then '000000000001' when 'Problem report' then '000000000002' else '000000000003' end)::uuid
where reporter_user_id::text like '71000000-%';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$select * from public.platform_admins$$,'42501',null,'Normal user cannot read platform_admins');
select extensions.throws_ok($$select * from public.network_reports$$,'42501',null,'Normal user cannot read network_reports');
select extensions.throws_ok($$insert into public.platform_admins(user_id) values (auth.uid())$$,'42501',null,'No self enrollment');
select extensions.throws_ok($$select * from public.list_network_reports_for_moderation()$$,'42501','platform_admin_required','Normal user cannot read moderation RPC');
select extensions.throws_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','closed','Secret')$$,'42501','platform_admin_required','Normal user cannot moderate');
select extensions.throws_ok($$select public.moderate_network_report('ffffffff-ffff-4fff-8fff-ffffffffffff','closed',null)$$,'42501','platform_admin_required','ID probing denied before lookup');
select extensions.throws_ok($$update public.network_reports set status='closed',admin_note='forged'$$,'42501',null,'Normal user cannot directly change status or note');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select extensions.is(public.is_platform_admin(),true,'Explicit account is admin');
select extensions.is((select count(*) from public.list_network_reports_for_moderation()),4::bigint,'Admin sees all four legitimate contexts');
select extensions.is((select reporter_name from public.list_network_reports_for_moderation() where id='76000000-0000-4000-8000-000000000001'),'Report author','Only relevant display name is projected');
select extensions.is((select origin from public.list_network_reports_for_moderation() where id='76000000-0000-4000-8000-000000000001'),'contact_request','Correct origin 1');
select extensions.is((select origin from public.list_network_reports_for_moderation() where id='76000000-0000-4000-8000-000000000002'),'problem_interest','Correct origin 2');
select extensions.is((select origin from public.list_network_reports_for_moderation() where id='76000000-0000-4000-8000-000000000003'),'find_intro','Correct origin 3');
select extensions.is((select origin from public.list_network_reports_for_moderation() where id='76000000-0000-4000-8000-000000000004'),'contact_request','Correct origin 4');
select extensions.throws_ok($$select * from public.network_reports$$,'42501',null,'Admin still has no unrestricted raw report access');
select extensions.throws_ok($$update public.network_reports set comment='rewritten'$$,'42501',null,'Admin cannot rewrite report contents');
select extensions.throws_ok($$delete from public.network_reports$$,'42501',null,'Admin cannot delete reports');
select extensions.throws_ok($$insert into public.platform_admins(user_id) values ('71000000-0000-4000-8000-000000000002')$$,'42501',null,'Moderator cannot appoint more admins');
select extensions.throws_ok($$select * from public.network_messages$$,'42501',null,'Admin gets no raw message access');
select extensions.throws_ok($$select * from public.list_network_messages('74000000-0000-4000-8000-000000000001')$$,'42501',null,'Admin cannot use manipulated conversation ID to read private history');
select extensions.throws_ok($$select * from public.list_network_reports_for_moderation('invalid')$$,'23514',null,'Invalid filter rejected');
select extensions.throws_ok($$select * from public.list_network_reports_for_moderation(null,51,0)$$,'23514',null,'Bounded response size');
select extensions.throws_ok($$select * from public.list_network_reports_for_moderation(null,25,-1)$$,'23514',null,'Negative offset rejected');
select extensions.throws_ok($$select public.moderate_network_report('74000000-0000-4000-8000-000000000001','closed',null)$$,'P0002','moderation_report_not_found','Conversation ID is not a report lookup');
select extensions.throws_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','banned',null)$$,'23514',null,'No unsupported sanctions');
select extensions.throws_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001',null,null)$$,'23514',null,'Null status rejected');
select extensions.throws_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','closed',repeat('x',2001))$$,'23514',null,'Oversized internal note rejected');
select extensions.lives_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','reviewed','  Internal only  ')$$,'Admin can review and record note');
select extensions.is((select admin_note from public.list_network_reports_for_moderation('reviewed')),'Internal only','Note stored and trimmed');
select extensions.ok((select moderated_at is not null and moderated_by=auth.uid() from public.list_network_reports_for_moderation('reviewed')),'Actor and time derived by DB');
select extensions.is((select count(*) from public.list_network_reports_for_moderation('open')),3::bigint,'Open filter');
select extensions.lives_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','closed','Internal only')$$,'Admin can close');
select extensions.is((select count(*) from public.list_network_reports_for_moderation('closed')),1::bigint,'Closed filter');
select extensions.is((select status from public.list_network_reports_for_moderation(null,1,0)),'open','Open reports sort before closed');
select extensions.is((select status from public.list_network_reports_for_moderation(null,1,3)),'closed','Pagination follows status priority');
select extensions.lives_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','open','')$$,'Admin can reopen');
select extensions.ok((select admin_note is null from public.list_network_reports_for_moderation() where id='76000000-0000-4000-8000-000000000001'),'Empty note clears');
select public.moderate_network_report('76000000-0000-4000-8000-000000000001','closed','Preserved confidential note');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is(public.report_network_conversation('74000000-0000-4000-8000-000000000001','harassment','Contact report'),'76000000-0000-4000-8000-000000000001'::uuid,'Participant RPC still returns only report UUID');
reset role;
select extensions.is((select status from public.network_reports where id='76000000-0000-4000-8000-000000000001'),'closed','Identical retry does not reopen closed report');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.report_network_conversation('74000000-0000-4000-8000-000000000001','harassment','New information');
reset role;
select extensions.ok((select status='open' and moderated_at is null and moderated_by is null and admin_note='Preserved confidential note' from public.network_reports where id='76000000-0000-4000-8000-000000000001'),'Changed report reopened without leaking or removing internal note');
select extensions.is((select count(*) from public.network_reports),4::bigint,'Existing report identity retained');
-- Revocation applies to the very next RPC, regardless of existing auth session.
delete from public.platform_admins where user_id='71000000-0000-4000-8000-000000000006';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select extensions.is(public.is_platform_admin(),false,'Revocation immediately changes helper');
select extensions.throws_ok($$select * from public.list_network_reports_for_moderation()$$,'42501','platform_admin_required','Revoked admin cannot list');
select extensions.throws_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','closed',null)$$,'42501','platform_admin_required','Revoked admin cannot write');
reset role;
select extensions.ok((select relrowsecurity from pg_class where oid='public.platform_admins'::regclass),'Admin allowlist has RLS');
select extensions.ok((select relrowsecurity from pg_class where oid='public.network_reports'::regclass),'Reports retain RLS');
set local role anon;
select set_config('request.jwt.claims','{}',true);

select extensions.throws_ok($$select * from public.platform_admins$$,'42501',null,'Anonymous access denied');
select extensions.throws_ok($$select * from public.network_reports$$,'42501',null,'Anonymous access denied');
select extensions.throws_ok($$select public.is_platform_admin()$$,'42501',null,'Anonymous access denied');
select extensions.throws_ok($$select * from public.list_network_reports_for_moderation()$$,'42501',null,'Anonymous access denied');
select extensions.throws_ok($$select public.moderate_network_report('76000000-0000-4000-8000-000000000001','closed',null)$$,'42501',null,'Anonymous access denied');
reset role;
select * from extensions.finish();
rollback;
